#!/bin/bash
set -euo pipefail

# =============================================================
#  build-ipa.sh  —  Build .IPA from Unity Xcode project
#  Generated by Unity Auto Build Tool
# =============================================================

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

BUILD_NAME="${BUILD_NAME:-NRO BEAR}"
BUNDLE_ID="${BUNDLE_ID:-com.DefaultCompany.DragonBoy002}"
METHOD="${METHOD:-unsigned}"
TEAM_ID="${TEAM_ID:-}"
SCHEME="Unity-iPhone"
CONFIGURATION="Release"

echo "============================================"
echo "  Unity iOS IPA Builder"
echo "  Build Name : $BUILD_NAME"
echo "  Bundle ID  : $BUNDLE_ID"
echo "  Method     : $METHOD"
echo "  Team ID    : $TEAM_ID"
echo "============================================"

# ── Check macOS ──
if [ "$(uname -s)" != "Darwin" ]; then
    echo "ERROR: This script must be run on macOS."
    exit 1
fi

# ── Check xcodebuild ──
if ! command -v xcodebuild &>/dev/null; then
    echo "ERROR: xcodebuild not found. Install Xcode."
    exit 1
fi

cd "$PROJECT_DIR"

# ── Verify IL2CPP libraries ──
check_lib() {
    local libpath="$1"
    if [ ! -f "$libpath" ]; then
        echo "WARNING: $libpath not found!"
        return 1
    fi
    local size
    size=$(stat -f%z "$libpath" 2>/dev/null || stat --printf="%s" "$libpath" 2>/dev/null || echo "0")
    if [ "$size" -lt 1048576 ]; then
        echo "WARNING: $libpath is too small ($size bytes) — likely a Git LFS pointer!"
        echo "Run: git lfs pull"
        return 1
    fi
    echo "OK: $libpath ($size bytes)"
    return 0
}

echo ""
echo "Checking IL2CPP libraries..."
check_lib "Libraries/libiPhone-lib.a" || true
check_lib "Libraries/libil2cpp.a" || true
echo ""

# ── Detect .xcodeproj ──
XCODEPROJ=""
if [ -d "Unity-iPhone.xcodeproj" ]; then
    XCODEPROJ="Unity-iPhone.xcodeproj"
elif [ -d "${BUILD_NAME}.xcodeproj" ]; then
    XCODEPROJ="${BUILD_NAME}.xcodeproj"
else
    XCODEPROJ=$(find . -maxdepth 1 -name "*.xcodeproj" -print -quit | sed 's|^\\./||')
fi

if [ -z "$XCODEPROJ" ]; then
    echo "ERROR: No .xcodeproj found in $PROJECT_DIR"
    exit 1
fi
echo "Using project: $XCODEPROJ"

# ── Build based on METHOD ──
if [ "$METHOD" = "unsigned" ]; then
    echo ""
    echo ">>> Building UNSIGNED IPA..."
    xcodebuild build \
        -project "$XCODEPROJ" \
        -scheme "$SCHEME" \
        -configuration "$CONFIGURATION" \
        -sdk iphoneos \
        -derivedDataPath build/DerivedData \
        CODE_SIGNING_REQUIRED=NO \
        CODE_SIGNING_ALLOWED=NO \
        CODE_SIGN_IDENTITY="" \
        PROVISIONING_PROFILE="" \
        | tail -20

    echo ""
    echo ">>> Packaging unsigned IPA..."
    APP_PATH=$(find build/DerivedData -name "*.app" -path "*/Release-iphoneos/*" | head -1)
    if [ -z "$APP_PATH" ]; then
        echo "ERROR: .app not found after build."
        exit 1
    fi

    rm -rf Payload
    mkdir -p Payload
    cp -R "$APP_PATH" Payload/

    IPA_NAME="IPA - ${BUILD_NAME}.ipa"
    zip -r -q "$IPA_NAME" Payload/
    rm -rf Payload

    echo "SUCCESS: Created $IPA_NAME ($(du -h "$IPA_NAME" | cut -f1))"

else
    echo ""
    echo ">>> Building signed IPA (method=$METHOD)..."

    if [ -z "$TEAM_ID" ]; then
        echo "ERROR: TEAM_ID required for method=$METHOD"
        exit 1
    fi

    ARCHIVE_PATH="build/${BUILD_NAME}.xcarchive"

    xcodebuild archive \
        -project "$XCODEPROJ" \
        -scheme "$SCHEME" \
        -configuration "$CONFIGURATION" \
        -sdk iphoneos \
        -archivePath "$ARCHIVE_PATH" \
        DEVELOPMENT_TEAM="$TEAM_ID" \
        CODE_SIGN_STYLE="Automatic" \
        | tail -20

    EXPORT_PLIST=""
    case "$METHOD" in
        ad-hoc)       EXPORT_PLIST="ios-build/ExportOptions-adhoc.plist" ;;
        development)  EXPORT_PLIST="ios-build/ExportOptions-adhoc.plist" ;;
        app-store-connect) EXPORT_PLIST="ios-build/ExportOptions-appstore.plist" ;;
    esac

    if [ ! -f "$EXPORT_PLIST" ]; then
        echo "ERROR: Export plist not found: $EXPORT_PLIST"
        exit 1
    fi

    IPA_EXPORT_DIR="build/ipa-export"
    xcodebuild -exportArchive \
        -archivePath "$ARCHIVE_PATH" \
        -exportPath "$IPA_EXPORT_DIR" \
        -exportOptionsPlist "$EXPORT_PLIST"

    IPA_FILE=$(find "$IPA_EXPORT_DIR" -name "*.ipa" | head -1)
    if [ -z "$IPA_FILE" ]; then
        echo "ERROR: .ipa not found after export."
        exit 1
    fi

    IPA_NAME="IPA - ${BUILD_NAME}.ipa"
    cp "$IPA_FILE" "$IPA_NAME"
    echo "SUCCESS: Created $IPA_NAME ($(du -h "$IPA_NAME" | cut -f1))"
fi

echo ""
echo "============================================"
echo "  Build complete!"
echo "============================================"
